class BstNode(var value: Int, var left: BstNode? = null, var right: BstNode? = null)

fun insert(root: BstNode?, value: Int): BstNode {
    if (root == null) return BstNode(value)
    if (value < root.value) root.left = insert(root.left, value)
    else if (value > root.value) root.right = insert(root.right, value)
    return root
}

fun search(root: BstNode?, value: Int): Boolean {
    var node = root
    while (node != null) {
        when {
            value == node.value -> return true
            value < node.value -> node = node.left
            else -> node = node.right
        }
    }
    return false
}

class MinHeap {
    private val a = mutableListOf<Int>()

    fun push(x: Int) {
        a.add(x)
        var i = a.size - 1
        while (i > 0) {
            val parent = (i - 1) / 2
            if (a[parent] <= a[i]) break
            a[parent] = a[i].also { a[i] = a[parent] }
            i = parent
        }
    }

    fun peek(): Int? = a.firstOrNull()
}

class Trie {
    private class Node {
        val next = HashMap<Char, Node>()
        var isEnd = false
    }
    private val root = Node()

    fun insert(word: String) {
        var node = root
        for (c in word) node = node.next.getOrPut(c) { Node() }
        node.isEnd = true
    }

    fun startsWith(prefix: String): Boolean {
        var node = root
        for (c in prefix) node = node.next[c] ?: return false
        return true
    }
}

class Graph {
    private val adjacency = mutableMapOf<Int, MutableList<Int>>()

    fun addEdge(from: Int, to: Int) {
        adjacency.getOrPut(from) { mutableListOf() }.add(to)
        adjacency.getOrPut(to) { mutableListOf() }.add(from)
    }

    fun bfs(start: Int): List<Int> {
        val visited = mutableSetOf(start)
        val order = mutableListOf<Int>()
        val queue = ArrayDeque(listOf(start))

        while (queue.isNotEmpty()) {
            val node = queue.removeFirst()
            order.add(node)
            for (neighbor in adjacency[node].orEmpty()) {
                if (visited.add(neighbor)) queue.addLast(neighbor)
            }
        }
        return order
    }
}

// tree sized 2n; build and query for range sums.
fun query(tree: IntArray, node: Int, lo: Int, hi: Int, l: Int, r: Int): Int {
    if (r < lo || hi < l) return 0                 // no overlap
    if (l <= lo && hi <= r) return tree[node]      // full overlap
    val mid = (lo + hi) / 2
    return query(tree, 2 * node, lo, mid, l, r) +
           query(tree, 2 * node + 1, mid + 1, hi, l, r)
}

class Fenwick(n: Int) {
    private val tree = IntArray(n + 1)   // 1-indexed

    fun update(i: Int, delta: Int) {
        var x = i
        while (x < tree.size) { tree[x] += delta; x += x and -x }
    }

    fun prefix(i: Int): Int {
        var x = i; var sum = 0
        while (x > 0) { sum += tree[x]; x -= x and -x }
        return sum
    }
}

class DisjointSet(n: Int) {
    private val parent = IntArray(n) { it }
    private val rank = IntArray(n)

    fun find(x: Int): Int {
        if (parent[x] != x) parent[x] = find(parent[x])   // path compression
        return parent[x]
    }

    fun union(a: Int, b: Int) {
        val ra = find(a); val rb = find(b)
        if (ra == rb) return
        when {                                            // union by rank
            rank[ra] < rank[rb] -> parent[ra] = rb
            rank[ra] > rank[rb] -> parent[rb] = ra
            else -> { parent[rb] = ra; rank[ra]++ }
        }
    }
}

// Rotate right around y to fix a left-heavy imbalance.
fun rotateRight(y: Node): Node {
    val x = y.left!!
    y.left = x.right
    x.right = y
    y.height = 1 + maxOf(height(y.left), height(y.right))
    x.height = 1 + maxOf(height(x.left), height(x.right))
    return x                 // x is the new subtree root
}

