import numpy as np

def step(z):
    return 1 if z >= 0 else 0

def train(X, y, lr=0.1, epochs=20):
    w = np.zeros(X.shape[1])
    b = 0.0
    for _ in range(epochs):
        for xi, target in zip(X, y):
            pred = step(w @ xi + b)
            error = target - pred
            w += lr * error * xi   # only moves on mistakes
            b += lr * error
    return w, b

class RandomForest(
    private val treeCount: Int = 100,
    private val featuresPerSplit: Int? = null,   // null -> sqrt(p)
) {
    private val trees = mutableListOf<DecisionTree>()

    fun fit(x: Array<DoubleArray>, y: IntArray) {
        val n = x.size
        val p = x[0].size
        val m = featuresPerSplit ?: Math.sqrt(p.toDouble()).toInt().coerceAtLeast(1)

        repeat(treeCount) {
            // Bootstrap: n draws WITH replacement, so rows repeat and some are omitted.
            val rows = IntArray(n) { (0 until n).random() }
            val tree = DecisionTree(featureSubsetSize = m)
            tree.fit(rows.map { x[it] }.toTypedArray(), rows.map { y[it] }.toIntArray())
            trees += tree
        }
    }

    // Majority vote across the ensemble.
    fun predict(sample: DoubleArray): Int =
        trees.map { it.predict(sample) }
            .groupingBy { it }
            .eachCount()
            .maxBy { it.value }
            .key
}

class GradientBoosting(
    private val rounds: Int = 200,
    private val learningRate: Double = 0.1,
    private val maxDepth: Int = 3,
) {
    private var base = 0.0
    private val trees = mutableListOf<RegressionTree>()

    fun fit(x: Array<DoubleArray>, y: DoubleArray) {
        base = y.average()                       // F0: the constant that minimizes MSE
        val prediction = DoubleArray(y.size) { base }

        repeat(rounds) {
            // For squared error the negative gradient IS the residual.
            val residuals = DoubleArray(y.size) { i -> y[i] - prediction[i] }

            val tree = RegressionTree(maxDepth).apply { fit(x, residuals) }
            trees += tree

            for (i in x.indices) prediction[i] += learningRate * tree.predict(x[i])
        }
    }

    fun predict(sample: DoubleArray): Double =
        base + trees.sumOf { learningRate * it.predict(sample) }
}

// Refit on many bootstrap samples and watch how the predictions at a fixed
// point scatter. The spread is variance; the offset of their mean is bias.
fun biasVariance(
    fitModel: (Array<DoubleArray>, DoubleArray) -> (DoubleArray) -> Double,
    samples: List<Pair<Array<DoubleArray>, DoubleArray>>,
    probe: DoubleArray,
    truth: Double,
): Triple<Double, Double, Double> {
    val predictions = samples.map { (x, y) -> fitModel(x, y)(probe) }
    val mean = predictions.average()

    val bias = mean - truth
    val variance = predictions.sumOf { (it - mean) * (it - mean) } / predictions.size
    val error = predictions.sumOf { (truth - it) * (truth - it) } / predictions.size

    return Triple(bias * bias, variance, error)   // bias² + variance ≈ error
}

enum class Penalty { NONE, L1, L2 }

fun trainLinear(
    x: Array<DoubleArray>,
    y: DoubleArray,
    penalty: Penalty,
    lambda: Double = 0.01,
    lr: Double = 0.05,
    epochs: Int = 500,
): DoubleArray {
    val w = DoubleArray(x[0].size)
    var b = 0.0

    repeat(epochs) {
        val gradW = DoubleArray(w.size)
        var gradB = 0.0
        for (i in x.indices) {
            val error = (x[i].indices.sumOf { j -> w[j] * x[i][j] } + b) - y[i]
            for (j in w.indices) gradW[j] += error * x[i][j]
            gradB += error
        }

        for (j in w.indices) {
            // The penalty gradient: 2λw for ridge, λ·sign(w) for lasso.
            val reg = when (penalty) {
                Penalty.NONE -> 0.0
                Penalty.L2 -> 2 * lambda * w[j]
                Penalty.L1 -> lambda * Math.signum(w[j])
            }
            w[j] -= lr * (gradW[j] / x.size + reg)
        }
        b -= lr * gradB / x.size          // the intercept is never penalized
    }
    return w
}

data class Confusion(val tp: Int, val fp: Int, val fn: Int, val tn: Int) {
    val accuracy get() = (tp + tn).toDouble() / (tp + fp + fn + tn)
    val precision get() = if (tp + fp == 0) 0.0 else tp.toDouble() / (tp + fp)
    val recall get() = if (tp + fn == 0) 0.0 else tp.toDouble() / (tp + fn)
    val f1 get() = if (precision + recall == 0.0) 0.0
        else 2 * precision * recall / (precision + recall)
}

fun confusionAt(scores: DoubleArray, labels: IntArray, threshold: Double): Confusion {
    var tp = 0; var fp = 0; var fn = 0; var tn = 0
    for (i in scores.indices) {
        val predictedPositive = scores[i] >= threshold
        when {
            predictedPositive && labels[i] == 1 -> tp++
            predictedPositive && labels[i] == 0 -> fp++
            !predictedPositive && labels[i] == 1 -> fn++
            else -> tn++
        }
    }
    return Confusion(tp, fp, fn, tn)
}

// AUC as the probability that a positive outranks a negative.
fun rocAuc(scores: DoubleArray, labels: IntArray): Double {
    val positives = scores.indices.filter { labels[it] == 1 }
    val negatives = scores.indices.filter { labels[it] == 0 }
    if (positives.isEmpty() || negatives.isEmpty()) return 0.5
    var wins = 0.0
    for (p in positives) for (n in negatives) {
        wins += when {
            scores[p] > scores[n] -> 1.0
            scores[p] == scores[n] -> 0.5
            else -> 0.0
        }
    }
    return wins / (positives.size * negatives.size)
}

from itertools import combinations

def apriori(transactions, minsup):
    n = len(transactions)
    items = {i for t in transactions for i in t}
    frequent, level = {}, {
        frozenset([i]) for i in items
        if sum(i in t for t in transactions) / n >= minsup
    }

    k = 1
    while level:
        for s in level:
            frequent[s] = sum(s <= t for t in transactions) / n
        k += 1

        # Join, then prune. The prune is what makes this tractable: a candidate
        # with any infrequent (k-1)-subset cannot be frequent, and rejecting it
        # here costs nothing while counting it would cost a database pass.
        candidates = {a | b for a in level for b in level if len(a | b) == k}
        candidates = {
            c for c in candidates
            if all(frozenset(s) in level for s in combinations(c, k - 1))
        }
        level = {
            c for c in candidates
            if sum(c <= t for t in transactions) / n >= minsup
        }
    return frequent

def eclat(transactions, minsup_count):
    # One pass: transpose into tid-lists. The database is not read again.
    tid_lists = {}
    for i, t in enumerate(transactions):
        for item in t:
            tid_lists.setdefault(item, set()).add(i)

    items = sorted(
        (k for k, v in tid_lists.items() if len(v) >= minsup_count),
        key=lambda k: len(tid_lists[k]),
    )

    found = {}

    def extend(prefix, tids, rest):
        for idx, item in enumerate(rest):
            merged = tids & tid_lists[item]        # support IS the intersection
            if len(merged) >= minsup_count:
                new_prefix = prefix | {item}
                found[frozenset(new_prefix)] = len(merged)
                extend(new_prefix, merged, rest[idx + 1:])

    extend(set(), set(range(len(transactions))), items)
    return found

def declat(transactions, minsup_count):
    tid_lists = {}
    for i, t in enumerate(transactions):
        for item in t:
            tid_lists.setdefault(item, set()).add(i)

    items = [k for k, v in tid_lists.items() if len(v) >= minsup_count]
    found = {}

    def extend(prefix, prefix_support, diffs, rest):
        for idx, (item, d_item) in enumerate(rest):
            # d(Xy) = d(y) - d(X): the transactions X has and Xy does not.
            d = d_item - diffs
            support = prefix_support - len(d)
            if support >= minsup_count:
                new_prefix = prefix | {item}
                found[frozenset(new_prefix)] = support
                extend(new_prefix, support, d, rest[idx + 1:])

    n = len(transactions)
    roots = [(k, set(range(n)) - tid_lists[k]) for k in items]
    extend(set(), n, set(), roots)
    return found

# On dense data a tid-list is nearly the whole database and a diffset is nearly
# empty, so this is the difference between a method that runs and one that does not.
# On sparse data it is the other way round -- measure, do not assume.

from collections import Counter, defaultdict

class Node:
    def __init__(self, item, parent):
        self.item, self.parent = item, parent
        self.count, self.children = 1, {}

def build_tree(transactions, minsup_count):
    counts = Counter(i for t in transactions for i in t)
    order = [i for i, c in counts.most_common() if c >= minsup_count]
    rank = {item: r for r, item in enumerate(order)}

    root, header = Node(None, None), defaultdict(list)
    for t in transactions:
        # Drop infrequent items, then sort by GLOBAL frequency. This ordering is
        # the entire reason the tree compresses -- sort by anything else and
        # transactions stop sharing prefixes.
        items = sorted((i for i in t if i in rank), key=lambda i: rank[i])
        node = root
        for item in items:
            if item in node.children:
                node.children[item].count += 1     # no allocation at all
            else:
                child = Node(item, node)
                node.children[item] = child
                header[item].append(child)
            node = node.children[item]
    return root, header, order

