import torch.nn as nn

class FeedForward(nn.Module):
    def __init__(self, d, hidden):
        super().__init__()
        self.up, self.down, self.act = nn.Linear(d, hidden), nn.Linear(hidden, d), nn.GELU()

    def forward(self, x):
        return self.down(self.act(self.up(x)))

# GEGLU, from the "GLU Variants Improve Transformer" line of work: split the
# projection and use half of it as a gate. T5 v1.1 and PaLM use this.
class GeGLU(nn.Module):
    def __init__(self, d, hidden):
        super().__init__()
        # 2/3 the hidden size keeps the parameter count matched -- worth doing,
        # or the comparison against plain GELU is not a fair one.
        self.up = nn.Linear(d, 2 * hidden)
        self.down = nn.Linear(hidden, d)
        self.act = nn.GELU()

    def forward(self, x):
        a, b = self.up(x).chunk(2, dim=-1)
        return self.down(self.act(a) * b)

class Adam(
    private val size: Int,
    private val lr: Double = 1e-3,
    private val beta1: Double = 0.9,
    private val beta2: Double = 0.999,
    private val eps: Double = 1e-8,
) {
    private val m = DoubleArray(size)      // first moment: momentum
    private val v = DoubleArray(size)      // second moment: per-parameter scale
    private var t = 0

    fun step(params: DoubleArray, grads: DoubleArray) {
        t++
        for (i in 0 until size) {
            m[i] = beta1 * m[i] + (1 - beta1) * grads[i]
            v[i] = beta2 * v[i] + (1 - beta2) * grads[i] * grads[i]

            // Both moments start at 0, which biases early steps toward zero.
            val mHat = m[i] / (1 - Math.pow(beta1, t.toDouble()))
            val vHat = v[i] / (1 - Math.pow(beta2, t.toDouble()))

            // Large recent gradients shrink the step; tiny ones enlarge it.
            params[i] -= lr * mHat / (Math.sqrt(vHat) + eps)
        }
    }
}

class BatchNorm(features: Int, private val eps: Double = 1e-5, private val momentum: Double = 0.1) {
    private val gamma = DoubleArray(features) { 1.0 }
    private val beta = DoubleArray(features)
    private val runningMean = DoubleArray(features)
    private val runningVar = DoubleArray(features) { 1.0 }

    // batch[sample][feature]
    fun forward(batch: Array<DoubleArray>, training: Boolean): Array<DoubleArray> {
        val n = batch.size
        val f = gamma.size
        val out = Array(n) { DoubleArray(f) }

        for (j in 0 until f) {
            val mean: Double
            val variance: Double
            if (training) {
                mean = (0 until n).sumOf { batch[it][j] } / n
                variance = (0 until n).sumOf { val d = batch[it][j] - mean; d * d } / n
                // Keep an EMA so inference does not need a batch.
                runningMean[j] = (1 - momentum) * runningMean[j] + momentum * mean
                runningVar[j] = (1 - momentum) * runningVar[j] + momentum * variance
            } else {
                mean = runningMean[j]
                variance = runningVar[j]
            }

            val denom = Math.sqrt(variance + eps)
            for (i in 0 until n) out[i][j] = gamma[j] * (batch[i][j] - mean) / denom + beta[j]
        }
        return out
    }
}

class Dropout(private val p: Double = 0.5) {
    private var mask: DoubleArray? = null

    fun forward(x: DoubleArray, training: Boolean): DoubleArray {
        if (!training || p <= 0.0) return x        // full network at inference

        val keep = 1.0 - p
        // Scale by 1/keep now so the expected value matches the un-dropped layer.
        val m = DoubleArray(x.size) { if (Math.random() < keep) 1.0 / keep else 0.0 }
        mask = m
        return DoubleArray(x.size) { i -> x[i] * m[i] }
    }

    // The backward pass must reuse the SAME mask that was sampled going forward.
    fun backward(gradOut: DoubleArray): DoubleArray {
        val m = mask ?: return gradOut
        return DoubleArray(gradOut.size) { i -> gradOut[i] * m[i] }
    }
}

class TransferModel(private val backbone: Network, private val head: Network) {

    // Stage 1 — backbone frozen, only the new head learns.
    fun trainHead(data: Dataset, epochs: Int = 5, lr: Double = 1e-3) {
        backbone.trainable = false
        for (batch in data.epochs(epochs)) {
            val features = backbone.forward(batch.x, training = false)
            val loss = head.trainStep(features, batch.y, lr)
            data.log(loss)
        }
    }

    // Stage 2 — unfreeze the top layers, tiny learning rate.
    fun fineTune(data: Dataset, epochs: Int = 3, lr: Double = 1e-5, unfreezeTop: Int = 2) {
        backbone.trainable = true
        backbone.layers.dropLast(unfreezeTop).forEach { it.trainable = false }
        for (batch in data.epochs(epochs)) {
            val features = backbone.forward(batch.x, training = true)
            val loss = head.trainStep(features, batch.y, lr)
            backbone.backward(head.inputGradient, lr)   // same small rate
            data.log(loss)
        }
    }
}

import torch, torch.nn as nn

def block(c_in, c_out):
    return nn.Sequential(
        nn.Conv2d(c_in, c_out, 3, padding=1), nn.BatchNorm2d(c_out), nn.ReLU(),
        nn.Conv2d(c_out, c_out, 3, padding=1), nn.BatchNorm2d(c_out), nn.ReLU(),
    )

class Up(nn.Module):
    def __init__(self, c_in, c_out):
        super().__init__()
        self.up = nn.ConvTranspose2d(c_in, c_out, 2, stride=2)
        self.conv = block(c_out * 2, c_out)      # *2: the skip is CONCATENATED

    def forward(self, x, skip):
        return self.conv(torch.cat([self.up(x), skip], dim=1))

# Addition (ResNet's operator) forces the two signals into one channel budget and
# commits to a fixed mixture. Concatenation keeps both and lets the following
# convolution learn the mixture per channel -- which is why the block after the
# concat has twice the input channels, and why U-Net's decoder is not cheap.

from collections import defaultdict

def left_context_ceiling(corpus):
    "Best possible accuracy for any model that reads left to right."
    groups = defaultdict(list)
    for words, tags in corpus:
        for i, tag in enumerate(tags):
            groups[tuple(words[:i + 1])].append(tag)   # the prefix IS the state

    best = sum(max(tags.count(t) for t in set(tags)) for tags in groups.values())
    return best / sum(len(tags) for _, tags in corpus)

# Run this before reaching for a bigger model. If the ceiling is 0.90 and your
# unidirectional tagger scores 0.89, the missing point is not in the optimizer,
# the embeddings or the layer count -- it is in the direction. No amount of
# capacity buys a distinction the input to the classifier does not contain.

import torch
import torch.nn as nn

@torch.no_grad()
def contexts(model, sources):
    return torch.cat([model.encoder(s)[1].squeeze(0) for s in sources])

def probe(model, sources, position, hidden, vocab, steps=400):
    "How recoverable is source[position] from the context vector alone?"
    x = contexts(model, sources)                 # encoder frozen: no grad above
    y = torch.tensor([s[0, position].argmax() for s in sources])
    readout = nn.Linear(hidden, vocab)
    optimizer = torch.optim.Adam(readout.parameters(), lr=0.05)
    for _ in range(steps):
        loss = nn.functional.cross_entropy(readout(x), y)
        optimizer.zero_grad(); loss.backward(); optimizer.step()
    return (readout(x).argmax(1) == y).float().mean().item()

# Run it per position and read the shape, not the average. A profile that slopes
# up toward the end of the source is recency -- the vector is holding the tail.
# That is the diagnosis reversal treats, and the one attention removes outright.

import torch

@torch.no_grad()
def beam_search(model, context, k=5, max_len=50, alpha=0.0):
    "alpha=0 sorts by total log-prob; alpha=1 sorts by log-prob per token."
    beams = [([], 0.0, context)]           # tokens, score, decoder state
    finished = []

    for _ in range(max_len):
        candidates = []
        for tokens, score, state in beams:
            logits, next_state = model.step(state, tokens[-1] if tokens else SOS)
            for token, logp in enumerate(torch.log_softmax(logits, -1)):
                if token == EOS:
                    finished.append((tokens, score + logp.item()))
                else:
                    candidates.append((tokens + [token], score + logp.item(), next_state))
        if not candidates:
            break
        beams = sorted(candidates, key=lambda c: -c[1])[:k]

    finished += [(t, s) for t, s, _ in beams]
    return max(finished, key=lambda c: c[1] / (len(c[0]) ** alpha if alpha else 1))

# alpha is not a free win. It lengthens outputs, which helps when the model stops
# too early and hurts when it does not -- so measure it on your own data rather
# than copying a value out of a paper written about a different task.

@torch.no_grad()
def error_split(model, dataset, k=5):
    "Sort every failure into 'the search lost it' and 'the model prefers wrong'."
    correct = search_errors = model_errors = 0
    for source, gold in dataset:
        predicted, score = beam_search(model, model.encode(source), k=k)
        if predicted == gold:
            correct += 1
        elif model.score(source, gold) > score:
            search_errors += 1        # widen the beam
        else:
            model_errors += 1         # a wider beam cannot help
    return correct, search_errors, model_errors

# On the lab's model: (35, 1, 84) at k=1 and (36, 0, 84) at k=10. Nine tenths of
# the failures are the model's ranking, so the next hour belongs in the data, the
# architecture or the objective -- not in the decoder.

class Diffusion(private val steps: Int = 1000, private val net: NoisePredictor) {
    // Linear beta schedule and its cumulative products.
    private val beta = DoubleArray(steps) { 1e-4 + (0.02 - 1e-4) * it / (steps - 1) }
    private val alpha = DoubleArray(steps) { 1 - beta[it] }
    private val alphaBar = DoubleArray(steps).also {
        var running = 1.0
        for (t in 0 until steps) { running *= alpha[t]; it[t] = running }
    }

    // One training step: corrupt to a random t, ask the net for the noise back.
    fun trainStep(x0: DoubleArray, lr: Double): Double {
        val t = (0 until steps).random()
        val noise = DoubleArray(x0.size) { gaussian() }
        val xt = DoubleArray(x0.size) { i ->
            Math.sqrt(alphaBar[t]) * x0[i] + Math.sqrt(1 - alphaBar[t]) * noise[i]
        }
        return net.trainStep(xt, t, target = noise, lr = lr)   // MSE against the true noise
    }

    // Sampling: start from pure noise and walk the reverse chain.
    fun sample(size: Int): DoubleArray {
        var x = DoubleArray(size) { gaussian() }
        for (t in steps - 1 downTo 0) {
            val predicted = net.predict(x, t)
            val mean = DoubleArray(size) { i ->
                (x[i] - (beta[t] / Math.sqrt(1 - alphaBar[t])) * predicted[i]) / Math.sqrt(alpha[t])
            }
            x = if (t == 0) mean
            else DoubleArray(size) { i -> mean[i] + Math.sqrt(beta[t]) * gaussian() }
        }
        return x
    }
}

