from math import log, exp, inf

def logsumexp(xs):
    m = max(xs)
    return m + log(sum(exp(x - m) for x in xs)) if m > -inf else -inf

def forward_log(words):
    a = {t: (log(start[t]) + log(b(t, words[0]))) if b(t, words[0]) else -inf
         for t in tags}
    for w in words[1:]:
        a = {to: logsumexp([a[fr] + log(A[fr][to]) for fr in tags]) + log(b(to, w))
             if b(to, w) else -inf for to in tags}
    return logsumexp([a[t] + log(A[t]["</s>"]) for t in tags])

