def spans(tree, start=0, out=None):
    out = [] if out is None else out
    i = start
    for child in tree:
        if isinstance(child, Tree):
            i = spans(child, i, out)
        else:
            i += 1
    if tree.height() > 2:            # skip pre-terminals
        out.append((tree.label(), start, i))
    return i if out is None else (out, i)[0] and i

