def evaluate(policy, states, P, R, gamma=0.9, eps=1e-8):
    \"\"\"Compute V^pi for a FIXED policy. Note the sum over actions
    weighted by pi — not a max. That is the whole difference from
    value iteration.\"\"\"
    V = {s: 0.0 for s in states}
    while True:
        delta = 0.0
        for s in states:
