def epsilon_at(step, start=1.0, end=0.05, decay_steps=50_000):
    # Linear anneal: explore almost always at first, then settle into
    # a small floor so the agent can still recover from a changing world.
    frac = min(1.0, step / decay_steps)
    return start + frac * (end - start)

