def value_iteration(states, actions, P, R, gamma=0.9, eps=1e-8):
    V = {s: 0.0 for s in states}
    sweeps = 0
    while True:
        delta = 0.0
        for s in states:
            if is_terminal(s):
                continue
            old = V[s]
            # In-place: later states in this sweep already see the updated
            # values of earlier ones. Same fixed point, fewer sweeps.
            V[s] = max(sum(P[s][a][s2] * (R[s][a][s2] + gamma * V[s2])
                           for s2 in states)
                       for a in actions)
            delta = max(delta, abs(V[s] - old))
        sweeps += 1
        if delta < eps:
            return V, sweeps

def policy_iteration(states, actions, P, R, gamma=0.9):
    policy = {s: actions[0] for s in states}
    rounds = 0

    while True:
        rounds += 1
        # 1. Evaluate: solve for V^pi under the CURRENT policy.
        V = {s: 0.0 for s in states}
        while True:
            delta = 0.0
            for s in states:
                if is_terminal(s):
                    continue
                a = policy[s]
                v = sum(P[s][a][s2] * (R[s][a][s2] + gamma * V[s2])
                        for s2 in states)
                delta = max(delta, abs(v - V[s]))
                V[s] = v
            if delta < 1e-9:
                break

        # 2. Improve: act greedily on those values.
        stable = True
        for s in states:
            if is_terminal(s):
                continue
            best = max(actions, key=lambda a: sum(
                P[s][a][s2] * (R[s][a][s2] + gamma * V[s2]) for s2 in states))
            if best != policy[s]:
                stable = False
            policy[s] = best

        if stable:
            return policy, V, rounds

# Evaluation does not have to run to convergence. Truncate it at k sweeps and
# you get a family of algorithms:
#   k = 1        -> value iteration
#   k = infinity -> policy iteration
#   k = 5..20    -> usually the fastest in wall-clock terms
def modified_policy_iteration(states, actions, P, R, gamma=0.9, k=10):
    V = {s: 0.0 for s in states}
    policy = {s: actions[0] for s in states}
    while True:
        for _ in range(k):                       # partial evaluation
            V = {s: backup(s, policy[s], V, P, R, gamma) for s in states}
        new_policy = {s: greedy(s, V, P, R, gamma) for s in states}
        if new_policy == policy:
            return policy, V
        policy = new_policy

def value_iteration(states, actions, P, R, gamma=0.9, eps=1e-6):
    V = {s: 0.0 for s in states}
    sweeps = 0
    while True:
        delta = 0.0
        for s in states:
            if is_terminal(s):
                continue
            old = V[s]
            V[s] = max(sum(P[s][a][s2] * (R[s][a][s2] + gamma * V[s2])
                           for s2 in states)
                       for a in actions)
            delta = max(delta, abs(V[s] - old))
        sweeps += 1
        if delta < eps:
            bound = eps * gamma / (1 - gamma)
            policy = {s: max(actions, key=lambda a: sum(
                P[s][a][s2] * (R[s][a][s2] + gamma * V[s2]) for s2 in states))
                for s in states if not is_terminal(s)}
            return policy, V, sweeps, bound

def sarsa(env, episodes=4000, alpha=0.5, gamma=1.0, eps=0.1):
    Q = np.zeros((env.n_states, env.n_actions))

    def pick(s):
        if np.random.rand() < eps:
            return np.random.randint(env.n_actions)
        return int(Q[s].argmax())

    for _ in range(episodes):
        s = env.reset()
        a = pick(s)                       # chosen BEFORE the loop
        done = False
        while not done:
            s2, r, done = env.step(a)
            a2 = pick(s2)                 # the action actually to be taken
            # SARSA:      bootstrap off Q[s2, a2]  -- on-policy
            # Q-learning: bootstrap off Q[s2].max() -- off-policy
            target = r + (0.0 if done else gamma * Q[s2, a2])
            Q[s, a] += alpha * (target - Q[s, a])
            s, a = s2, a2                 # a2 is CARRIED, not re-sampled
    return Q

