def c(n):
    # Expected path length of an unsuccessful search in a BST of n nodes.
    if n <= 1:
        return 0.0
    return 2 * (np.log(n - 1) + 0.5772156649) - 2 * (n - 1) / n

def score(mean_path_length, n):
    return 2 ** (-mean_path_length / c(n))

