    return False

def merge(intervals):
    intervals.sort(key=lambda p: p[0])   # sort by start
    out = []
    for s, e in intervals:
        if out and s <= out[-1][1]:      # overlaps the last kept
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])           # disjoint — start fresh
    return out

