def find_corrupt(a):
    i = 0
    while i < len(a):
        home = a[i] - 1
        if a[i] != a[home]:            # target slot holds something else
            a[i], a[home] = a[home], a[i]
        else:
            i += 1                     # settled, or a duplicate
    for i, x in enumerate(a):
        if x != i + 1:
            return {"duplicate": x, "missing": i + 1}
    return None

def combination_sum(nums, target):
    nums.sort()                       # lets the prune below fire early
    out, path = [], []

    def walk(start, remaining):
        if remaining == 0:
            out.append(path[:])       # copy — path keeps mutating
            return
        for i in range(start, len(nums)):
            if nums[i] > remaining:
                break                 # sorted: everything after is worse
            path.append(nums[i])      # choose
            walk(i, remaining - nums[i])
            path.pop()                # un-choose

    walk(0, target)
    return out

def subsets(nums):
    nums.sort()                       # duplicates must be adjacent
    out, path = [], []

    def walk(start):
        out.append(path[:])
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue              # same value already tried at this depth
            path.append(nums[i])
            walk(i + 1)
            path.pop()

    walk(0)
    return out

from collections import deque

def level_order(root):
    if not root:
        return []
    q, levels = deque([root]), []
    while q:
        size = len(q)                 # freeze before pushing children
        level = []
        for _ in range(size):
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        levels.append(level)
    return levels

def path_sum(root, target):
    out, path = [], []

    def walk(node, remaining):
        if not node:
            return
        path.append(node.val)
        remaining -= node.val
        if not node.left and not node.right and remaining == 0:
            out.append(path[:])       # leaf and budget exactly spent
        else:
            walk(node.left, remaining)
            walk(node.right, remaining)
        path.pop()                    # un-choose

    walk(root, target)
    return out

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n                 # components

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]   # path compression
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False               # already together -> cycle edge
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.rank[ra] += self.rank[ra] == self.rank[rb]
        self.count -= 1
        return True

from collections import deque

def count_islands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != "1":
                continue
            islands += 1
            q = deque([(i, j)])
            grid[i][j] = "0"           # mark on enqueue, never on pop
            while q:
                r, c = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "1":
                        grid[nr][nc] = "0"
                        q.append((nr, nc))
    return islands

def two_singles(a):
    xor_all = 0
    for x in a:
        xor_all ^= x               # = p ^ q, the two unpaired values
    bit = xor_all & -xor_all       # a bit where p and q differ
    p = q = 0
    for x in a:
        if x & bit:
            p ^= x                 # group with the bit set
        else:
            q ^= x                 # group without it
    return p, q

import heapq

class MedianStream:
    def __init__(self):
        self.lo = []            # max-heap via negated values
        self.hi = []            # min-heap

    def add(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))   # largest of lo -> hi
        if len(self.hi) > len(self.lo):                    # keep lo the bigger half
            heapq.heappush(self.lo, -heapq.heappop(self.hi))

    def median(self):
        if len(self.lo) > len(self.hi):
            return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2

from collections import deque

def window_max(a, k):
    dq, out = deque(), []            # dq holds indices, a[dq] decreasing
    for i, x in enumerate(a):
        if dq and dq[0] <= i - k:
            dq.popleft()             # front slid out of the window
        while dq and a[dq[-1]] <= x:
            dq.pop()                 # dominated by the newer, larger x
        dq.append(i)
        if i >= k - 1:
            out.append(a[dq[0]])
    return out

def knapsack(weights, values, cap):
    dp = [0] * (cap + 1)
    for w, v in zip(weights, values):
        for c in range(cap, w - 1, -1):   # descending: each item used once
            dp[c] = max(dp[c], v + dp[c - w])
    return dp[cap]

def coin_change(coins, target):           # unbounded: ascending capacity
    dp = [0] + [float('inf')] * target
    for coin in coins:
        for c in range(coin, target + 1):
            dp[c] = min(dp[c], 1 + dp[c - coin])
    return -1 if dp[target] == float('inf') else dp[target]

def lcs(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1          # extend the match
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = i + j                          # empty prefix costs its length
            elif a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)      # 1-indexed

    def add(self, i, delta):           # point update
        i += 1
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i                # jump to the next covering block

    def prefix(self, i):               # sum of a[0..i]
        i += 1
        total = 0
        while i > 0:
            total += self.tree[i]
            i -= i & -i                # strip the lowest set bit
        return total

    def range_sum(self, l, r):
        return self.prefix(r) - (self.prefix(l - 1) if l else 0)

class Trie:
    def __init__(self):
        self.children = {}
        self.is_word = False

    def insert(self, word):
        node = self
        for ch in word:
            node = node.children.setdefault(ch, Trie())
        node.is_word = True

    def _walk(self, prefix):
        node = self
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.is_word

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

import heapq

def dijkstra(graph, src):                    # graph: u -> [(v, w), ...]
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float('inf')):
            continue                         # stale entry, already settled cheaper
        for v, w in graph.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def max_subarray(a):
    cur = best = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)        # extend the run, or restart at x
        best = max(best, cur)
    return best

def max_product(a):
    cur_max = cur_min = best = a[0]
    for x in a[1:]:
        candidates = (x, cur_max * x, cur_min * x)
        cur_max, cur_min = max(candidates), min(candidates)
        best = max(best, cur_max)    # a negative x can flip min into max
    return best

def rabin_karp(text, pattern):
    n, m = len(text), len(pattern)
    if m > n:
        return []
    B, M = 257, (1 << 61) - 1
    high = pow(B, m - 1, M)            # weight of the leading character

    def h(s):
        v = 0
        for ch in s:
            v = (v * B + ord(ch)) % M
        return v

    target, cur, hits = h(pattern), h(text[:m]), []
    for i in range(n - m + 1):
        if cur == target and text[i:i + m] == pattern:
            hits.append(i)             # verify: hashes can collide
        if i + m < n:
            cur = ((cur - ord(text[i]) * high) * B + ord(text[i + m])) % M
    return hits

def lower_bound(a, x):                     # first index with a[i] >= x
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid                       # keep mid as a candidate
    return lo                              # == len(a) if x is largest

def search_rotated(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == target:
            return mid
        if a[lo] <= a[mid]:                # left half is sorted
            if a[lo] <= target < a[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:                              # right half is sorted
            if a[mid] < target <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

from functools import lru_cache

def min_coins(coins, target):
    @lru_cache(maxsize=None)               # cache keyed by `rest`
    def best(rest):
        if rest == 0:
            return 0
        if rest < 0:
            return float('inf')
        return min((1 + best(rest - c) for c in coins), default=float('inf'))

    answer = best(target)
    return -1 if answer == float('inf') else answer

def grid_paths(rows, cols, blocked):       # explicit cache, two-argument state
    memo = {}
    def walk(r, c):
        if r >= rows or c >= cols or (r, c) in blocked:
            return 0
        if (r, c) == (rows - 1, cols - 1):
            return 1
        if (r, c) not in memo:
            memo[(r, c)] = walk(r + 1, c) + walk(r, c + 1)
        return memo[(r, c)]
    return walk(0, 0)

def count_inversions(a):
    def sort_count(xs):
        if len(xs) <= 1:
            return xs, 0
        mid = len(xs) // 2
        left, li = sort_count(xs[:mid])
        right, ri = sort_count(xs[mid:])
        merged, ci = [], 0
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i]); i += 1
            else:
                ci += len(left) - i      # left[i:] all outrank right[j]
                merged.append(right[j]); j += 1
        merged += left[i:] + right[j:]
        return merged, li + ri + ci
    return sort_count(a)[1]

def rotate_clockwise(m):                   # square, in place
    n = len(m)
    for r in range(n):
        for c in range(r + 1, n):
            m[r][c], m[c][r] = m[c][r], m[r][c]    # transpose
    for row in m:
        row.reverse()                              # then mirror

def spiral(m):
    if not m:
        return []
    top, bottom, left, right = 0, len(m) - 1, 0, len(m[0]) - 1
    out = []
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(m[top][c])
        top += 1
        for r in range(top, bottom + 1):
            out.append(m[r][right])
        right -= 1
        if top <= bottom:                          # guard the reverse passes
            for c in range(right, left - 1, -1):
                out.append(m[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                out.append(m[r][left])
            left += 1
    return out

from collections import deque

def is_bipartite(graph, n):
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue                       # component already done
        color[start] = 0
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    dq.append(v)
                elif color[v] == color[u]:
                    return False           # odd cycle
    return True

def has_directed_cycle(graph, n):
    state = [0] * n                        # 0 new, 1 on stack, 2 done
    def dfs(u):
        state[u] = 1
        for v in graph[u]:
            if state[v] == 1:
                return True                # back edge into the live path
            if state[v] == 0 and dfs(v):
                return True
        state[u] = 2
        return False
    return any(state[u] == 0 and dfs(u) for u in range(n))

import random

class RandomSet:
    def __init__(self):
        self.items = []                    # dense array for sampling
        self.index = {}                    # value -> position in items

    def insert(self, value):
        if value in self.index:
            return False
        self.index[value] = len(self.items)
        self.items.append(value)
        return True

    def remove(self, value):
        if value not in self.index:
            return False
        pos, last = self.index.pop(value), self.items[-1]
        if last != value:
            self.items[pos] = last         # swap the tail into the hole
            self.index[last] = pos
        self.items.pop()
        return True

    def get_random(self):
        return random.choice(self.items)   # dense array keeps this uniform

def decode(s):                             # "3[a2[c]]" -> "accaccacc"
    stack, cur, count = [], "", 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)   # multi-digit repeats
        elif ch == '[':
            stack.append((cur, count))     # save the enclosing context
            cur, count = "", 0
        elif ch == ']':
            prev, repeat = stack.pop()
            cur = prev + cur * repeat      # fold back into the parent
        else:
            cur += ch
    return cur

def is_balanced(s):
    pairs, stack = {')': '(', ']': '[', '}': '{'}, []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack                       # nothing left open

from bisect import bisect_right

def subset_sums(items):
    out = [0]
    for x in items:
        out += [s + x for s in out]        # 2^len(items) sums
    return out

def best_subset_sum(items, target):
    mid = len(items) // 2
    left = subset_sums(items[:mid])
    right = sorted(s for s in subset_sums(items[mid:]) if s <= target)
    best = 0
    for s in left:
        if s > target:
            continue
        i = bisect_right(right, target - s) - 1   # largest partner that fits
        if i >= 0:
            best = max(best, s + right[i])
    return best

import random

def reservoir(stream, k):
    kept = []
    for i, item in enumerate(stream, start=1):
        if i <= k:
            kept.append(item)
        else:
            j = random.randrange(i)        # 0 .. i-1
            if j < k:                      # replace with probability k/i
                kept[j] = item
    return kept

def shuffle(a):
    for i in range(len(a) - 1):
        j = random.randrange(i, len(a))    # suffix only — [i, n)
        a[i], a[j] = a[j], a[i]
    return a

def build(parent, n, LOG):                 # parent[root] = root
    up = [parent[:]] + [[0] * n for _ in range(LOG - 1)]
    for j in range(1, LOG):
        for v in range(n):
            up[j][v] = up[j - 1][up[j - 1][v]]
    return up

def kth_ancestor(up, v, k, LOG):
    for j in range(LOG):
        if k >> j & 1:                     # one jump per set bit
            v = up[j][v]
    return v

def lca(up, depth, u, v, LOG):
    if depth[u] < depth[v]:
        u, v = v, u
    u = kth_ancestor(up, u, depth[u] - depth[v], LOG)   # equalise depth
    if u == v:
        return u
    for j in reversed(range(LOG)):
        if up[j][u] != up[j][v]:           # jump while still apart
            u, v = up[j][u], up[j][v]
    return up[0][u]

def sort_three(a, pivot):
    low, mid, high = 0, 0, len(a) - 1
    while mid <= high:
        if a[mid] < pivot:
            a[low], a[mid] = a[mid], a[low]
            low += 1
            mid += 1                       # swapped-in value already classified
        elif a[mid] > pivot:
            a[mid], a[high] = a[high], a[mid]
            high -= 1                      # mid stays: new value is unexamined
        else:
            mid += 1
    return a

def move_zeroes(a):                        # two-region version
    write = 0
    for read in range(len(a)):
        if a[read] != 0:
            a[write], a[read] = a[read], a[write]
            write += 1
    return a

def expand(s, left, right):
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return left + 1, right                 # pointers overshot by one

def longest_palindrome(s):
    best = (0, 0)
    for i in range(len(s)):
        for lo, hi in (expand(s, i, i), expand(s, i, i + 1)):
            if hi - lo > best[1] - best[0]:
                best = (lo, hi)
    return s[best[0]:best[1]]

def count_palindromes(s):
    total = 0
    for i in range(len(s)):
        for lo, hi in (expand(s, i, i), expand(s, i, i + 1)):
            total += (hi - lo + 1) // 2    # every nested centre counts
    return total

def kth_smallest(root, k):
    stack, node = [], root
    while stack or node:
        while node:                        # push the left spine
            stack.append(node)
            node = node.left
        node = stack.pop()
        k -= 1
        if k == 0:
            return node.val                # stop early — no full traversal
        node = node.right
    return None

def is_valid_bst(root, low=float('-inf'), high=float('inf')):
    if not root:
        return True
    if not low < root.val < high:
        return False                       # bounds, not just the parent
    return (is_valid_bst(root.left, low, root.val)
            and is_valid_bst(root.right, root.val, high))

from bisect import bisect_left

def lis_length(a):
    tails = []
    for x in a:
        i = bisect_left(tails, x)          # first tail >= x
        if i == len(tails):
            tails.append(x)                # extends the longest chain
        else:
            tails[i] = x                   # a smaller tail is strictly better
    return len(tails)

def max_envelopes(envelopes):              # (width, height) nesting
    envelopes.sort(key=lambda e: (e[0], -e[1]))   # height descending on ties
    return lis_length([h for _, h in envelopes])  # so equal widths cannot chain

B = 32

class BitTrie:
    def __init__(self):
        self.child = [None, None]

    def insert(self, x):
        node = self
        for k in range(B - 1, -1, -1):     # most significant bit first
            b = (x >> k) & 1
            if node.child[b] is None:
                node.child[b] = BitTrie()
            node = node.child[b]

    def max_xor(self, x):
        node, best = self, 0
        for k in range(B - 1, -1, -1):
            b = (x >> k) & 1
            want = 1 - b                   # opposite bit sets this position
            if node.child[want] is not None:
                best |= 1 << k
                node = node.child[want]
            else:
                node = node.child[b]
        return best

def max_pair_xor(nums):
    trie, best = BitTrie(), 0
    trie.insert(nums[0])
    for x in nums[1:]:
        best = max(best, trie.max_xor(x))  # query before insert: pairs only
        trie.insert(x)
    return best

from functools import lru_cache

def first_player_wins(piles):
    @lru_cache(maxsize=None)
    def best(i, j):                        # mover's lead over the range i..j
        if i > j:
            return 0
        take_left = piles[i] - best(i + 1, j)     # opponent's lead is my loss
        take_right = piles[j] - best(i, j - 1)
        return max(take_left, take_right)
    return best(0, len(piles) - 1) > 0

def can_win_take_1_to_3(n):                # remove 1..3 stones, taking the last wins
    win = [False] * (n + 1)
    for total in range(1, n + 1):
        win[total] = any(not win[total - take]
                         for take in (1, 2, 3) if take <= total)
    return win[n]                          # losing exactly when n % 4 == 0

import heapq
from collections import Counter

def min_rooms(intervals):
    intervals.sort()                       # by start time
    ends = []                              # min-heap of end times
    for start, end in intervals:
        if ends and ends[0] <= start:
            heapq.heappop(ends)            # a room freed up in time
        heapq.heappush(ends, end)
    return len(ends)                       # peak concurrency

def schedule_with_cooldown(tasks, cooldown):
    counts = [-c for c in Counter(tasks).values()]   # max-heap via negation
    heapq.heapify(counts)
    time = 0
    while counts:
        cycle, waiting = [], cooldown + 1
        while waiting and counts:
            remaining = heapq.heappop(counts) + 1    # run one instance
            if remaining:
                cycle.append(remaining)    # still has work left
            time += 1
            waiting -= 1
        for remaining in cycle:
            heapq.heappush(counts, remaining)
        if counts:
            time += waiting                # idle out the rest of the cooldown
    return time
